extends CharacterBody2D

@export var bullet_scene: PackedScene = preload("res://bullet.tscn")
@export var shoot_cooldown: float = 0.3

var _time_since_last_shot: float = 0.0


func _physics_process(delta: float) -> void:
	_time_since_last_shot += delta

	if Input.is_action_pressed("move_right"):
		velocity.x = 200.0
	else:
		velocity.x = 0.0
	move_and_slide()

	if Input.is_action_pressed("shoot") and _time_since_last_shot >= shoot_cooldown:
		shoot()


func shoot() -> void:
	# ERRORE 1: Mancata azzeramento di _time_since_last_shot

	var bullet := bullet_scene.instantiate() as Node2D
	bullet.global_position = global_position

	# ERRORE 2: Aggiunge il proiettile a se stesso (Player) anziché alla scena principale
	add_child(bullet)

